        'def add(a, b):\n    return a + b\n\ndef check(desc, got, want):\n    status = "PASS" if got == want else "FAIL"\n    print(f"{status}: {desc} -> {got!r}")\n    assert got == want, (desc, got, want)\n\ncheck("two positives", add(2, 3), 5)\ncheck("negative cancels", add(-4, 4), 0)\ncheck("zero identity", add(7, 0), 7)\nprint("all green: 3 checks")',
