            'def project(base, rate, years):\n    return base * (1 + rate) ** years\n\ndef check_rel(desc, got, want, rel):\n    ok = abs(got - want) <= rel * abs(want)\n    print(("PASS" if ok else "FAIL") + f": {desc} -> {got!r}")\n    assert ok, (desc, got, want)\n\ncheck_rel("small base", project(100.0, 0.12, 3), 140.4928, 0.01)\ncheck_rel("large base", project(2500000.0, 0.12, 3), 3512320.0, 0.01)\ncheck_rel("flat", project(500.0, 0.0, 10), 500.0, 1e-9)\nprint("relative bands hold")',
