            'def make_session(role="viewer", expired=False):\n    return {"role": role, "expired": expired}\n\ndef can_edit(session):\n    return session["role"] in ("admin", "editor") and not session["expired"]\n\ndef check(desc, got, want):\n    print(("PASS" if got == want else "FAIL") + f": {desc} -> {got!r}")\n    assert got == want, (desc, got, want)\n\ncheck("admin fresh", can_edit(make_session("admin")), True)\ncheck("editor fresh", can_edit(make_session("editor")), True)\ncheck("admin expired", can_edit(make_session("admin", True)), False)\ncheck("viewer fresh", can_edit(make_session()), False)\nprint("factory matrix green")',
