            'def convert(usd, rate_fn):\n    return round(usd * rate_fn("USDINR"), 2)\n\nstub = lambda pair: 83.20\n\ndef check(desc, got, want):\n    print(("PASS" if got == want else "FAIL") + f": {desc} -> {got!r}")\n    assert got == want, (desc, got, want)\n\ncheck("ten dollars", convert(10, stub), 832.0)\ncheck("cents kept", convert(1.5, stub), 124.8)\ncheck("zero", convert(0, stub), 0.0)\nprint("rate stubbed")',
