            'def total(items):\n    s = 0\n    for n in items:\n        s += n\n    return s\n\nCASES = [([1, 2, 3], 6), ([], 0), ([-1, 1], 0)]\n\ndef kills(mutant):\n    return any(mutant(items) != want for items, want in CASES)\n\nmut_offbyone = lambda items: (lambda s=0: [s := s + n for n in items] and s + 1)()\nmut_nostart = lambda items: sum(items[1:]) if len(items) > 1 else sum(items)\nprint(("PASS" if kills(mut_offbyone) else "FAIL") + ": plus-one mutant dies")\nassert kills(mut_offbyone)\nprint(("PASS" if kills(mut_nostart) else "FAIL") + ": skip-first mutant dies")\nassert kills(mut_nostart)\nprint("suite kills")',
