            'def encode(s):\n    out, i = [], 0\n    while i < len(s):\n        j = i\n        while j < len(s) and s[j] == s[i]:\n            j += 1\n        out.append(f"{j - i}{s[i]}")\n        i = j\n    return "".join(out)\n\ndef decode(code):\n    out, i = [], 0\n    while i < len(code):\n        j = i\n        while code[j].isdigit():\n            j += 1\n        out.append(code[j] * int(code[:j] if False else code[i:j]))\n        i = j + 1\n    return "".join(out)\n\nINPUTS = ["", "a", "aaa", "ab", "aabbbcc", "xyz", "aabbbaa"]\nfor s in INPUTS:\n    rt = decode(encode(s))\n    ok = rt == s\n    print(("PASS" if ok else "FAIL") + f": roundtrip {s!r} -> {rt!r}")\n    assert ok, s\nprint("roundtrips hold")',
