            "Shrinking needs a fast predicate and a simplification strategy (delete halves, then singles); keep shrinks deterministic and time-boxed so the harness never hangs.",
            'def balanced(s):\n    depth = 0\n    for ch in s:\n        if ch == "(":\n            depth += 1\n        elif ch == ")":\n            depth -= 1\n        if depth < 0:\n            return False\n    return depth == 0\n\nbad = "((a)(b))(" \ncur = bad\nchanged = True\nwhile changed:\n    changed = False\n    for i in range(len(cur)):\n        cand = cur[:i] + cur[i + 1:]\n        if cand and not balanced(cand) and len(cand) < len(cur):\n            if not balanced(cand) and (not balanced(cur)):\n                cur = cand\n                changed = True\n                break\nprint(("PASS" if not balanced(cur) and len(cur) <= len(bad) else "FAIL") + f": shrunk {bad!r} -> {cur!r}")\nassert not balanced(cur) and len(cur) <= len(bad)\nassert balanced("()") and not balanced(")(")',
