            'def normalize(name):\n    if not isinstance(name, str):\n        raise TypeError(f"name must be str, got {type(name).__name__}")\n    return name.strip().lower()\n\ndef check(desc, got, want):\n    print(("PASS" if got == want else "FAIL") + f": {desc} -> {got!r}")\n    assert got == want, (desc, got, want)\n\ncheck("trims", normalize("  Ada "), "ada")\ntry:\n    normalize(42)\n    raise SystemExit("should raise")\nexcept TypeError as e:\n    print(f"PASS: non-string triaged -> {e}")\n    assert "int" in str(e)\nprint("else covered")',
