            "import time\n\nLEDGER = [(\"test_invoice_golden\", 0.5, \"fast: pure render\"),\n          (\"test_nightly_fuzz\", 300.0, \"slow: 10k-case sweep, nightly only\")]\n\ndef test_invoice_golden():\n    t0 = time.perf_counter()\n    assert 2 + 2 == 4\n    return time.perf_counter() - t0\n\nelapsed = test_invoice_golden()\nprint((\"PASS\" if elapsed < 0.5 else \"FAIL\") + f\": fast budget -> {elapsed:.4f}s\")\nassert elapsed < 0.5\nslow = [name for name, budget, _ in LEDGER if budget > 60]\nprint((\"PASS\" if slow == [\"test_nightly_fuzz\"] else \"FAIL\") + f\": slow listed -> {slow}\")\nassert slow == [\"test_nightly_fuzz\"]",
