            'import math\n\nPUBLIC = ["ceil", "floor", "sqrt", "pow"]\nmissing = [n for n in PUBLIC if not callable(getattr(math, n, None))]\nprint(("PASS" if not missing else "FAIL") + f": surface -> {PUBLIC}")\nassert not missing, missing\nimport inspect\narity = {n: len(inspect.signature(getattr(math, n)).parameters) for n in PUBLIC}\nprint(("PASS" if arity["pow"] == 2 else "FAIL") + f": arity -> {arity}")\nassert arity["pow"] == 2 and arity["sqrt"] == 1',
