            'records = []\n\ndef log(level, event, **fields):\n    records.append({"level": level, "event": event, **fields})\n\ndef checkout(user, total):\n    log("INFO", "checkout_ok", user=user, total=total)\n    return True\n\ncheckout("ada", 42.5)\nrec = records[0]\nprint(("PASS" if rec == {"level": "INFO", "event": "checkout_ok", "user": "ada", "total": 42.5} else "FAIL") + f": record -> {rec}")\nassert rec == {"level": "INFO", "event": "checkout_ok", "user": "ada", "total": 42.5}\nprint(("PASS" if rec["level"] == "INFO" and rec["event"] == "checkout_ok" else "FAIL") + ": routing fields")\nassert len(records) == 1',
