            'records = []\n\ndef stage_parse(line):\n    name, qty, price = line.split(",")\n    return {"name": name.strip(), "qty": int(qty), "price": float(price)}\n\ndef stage_price(rec):\n    return round(rec["qty"] * rec["price"], 2)\n\ndef pipeline(lines):\n    total = 0.0\n    for line in lines:\n        rec = stage_parse(line)\n        total += stage_price(rec)\n    total = round(total, 2)\n    records.append({"level": "INFO", "event": "batch_ok", "total": total})\n    return total\n\nt = pipeline(["apple,2,1.20", "pear,1,2.40"])\nprint(("PASS" if t == 4.80 and records == [{"level": "INFO", "event": "batch_ok", "total": 4.80}] else "FAIL") + f": total={t} log={records}")\nassert t == 4.80 and records[0]["total"] == 4.80\nprint("ensemble green")',
            "empty batch must total 0.00 and still log the batch record",
