            'runs = []\n\ndef attempt(name, pollutes):\n    if pollutes:\n        runs.append(name)\n    return len(runs)\n\ntests = [("t1", False), ("t2", False), ("t3", True), ("t4", False)]\nfirst_half = [n for n, p in tests[:2] for _ in [attempt(n, p)]]\nprint(("PASS" if runs == [] else "FAIL") + f": clean half leaves nothing -> {runs}")\nassert runs == []\nruns.clear()\nsecond_half = [n for n, p in tests[2:] for _ in [attempt(n, p)]]\nprint(("PASS" if runs == ["t3"] else "FAIL") + f": guilty half names t3 -> {runs}")\nassert runs == ["t3"]\nprint("bisected")',
